const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfo(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const cairns = ee.Geometry.Point([145.770859, -16.920334]).buffer(10000);     // 10 km
    const cooktown = ee.Geometry.Point([145.248920, -15.475923]).buffer(10000);  // 10 km
    const start = '2025-01-31';
    const end = '2025-02-05'; // exclusive
    const scale = 10000;

    // 2. Data Acquisition & Check
    let dataset = 'IMERG_V07_30min';
    let col = ee.ImageCollection('NASA/GPM_L3/IMERG_V07')
      .filterDate(start, end)
      .select('precipitationCal');
    let size = await getInfo(col.size());

    if (size === 0) {
      // Fallback to ERA5-Land hourly
      dataset = 'ERA5_LAND_HOURLY';
      col = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
        .filterDate(start, end)
        .select('total_precipitation');
      size = await getInfo(col.size());
      if (size === 0) {
        console.log('IMERG images: 0');
        console.log('ERA5-Land images: 0');
        console.log('C1');
        return;
      }
    }

    console.log(`${dataset} images: ${size}`);

    // 3. Processing: convert to mm and sum over time
    let sumImg;
    if (dataset === 'IMERG_V07_30min') {
      // precipitationCal is mm/hr at 30-min timestep -> mm = rate * 0.5 h
      sumImg = col.map(img => img.multiply(0.5).copyProperties(img, img.propertyNames()))
                  .sum()
                  .rename('rain');
    } else {
      // ERA5 total_precipitation is m over the hour -> mm = m * 1000
      sumImg = col.map(img => img.multiply(1000).copyProperties(img, img.propertyNames()))
                  .sum()
                  .rename('rain');
    }

    // 4. Reduce for both regions (mean across buffer, with pixel count)
    const reducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const cairnsDict = ee.Dictionary(sumImg.reduceRegion({
      reducer: reducer,
      geometry: cairns,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    const cookDict = ee.Dictionary(sumImg.reduceRegion({
      reducer: reducer,
      geometry: cooktown,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));

    const cairnsRes = await getInfo(cairnsDict);
    const cookRes = await getInfo(cookDict);

    const cairnsPx = cairnsRes ? (cairnsRes['rain_count'] || 0) : 0;
    const cookPx = cookRes ? (cookRes['rain_count'] || 0) : 0;
    if (cairnsPx === 0 || cookPx === 0) {
      console.log(`Cairns pixels: ${cairnsPx}, Cooktown pixels: ${cookPx}`);
      console.log('C2');
      return;
    }

    const cairnsMM = cairnsRes['rain_mean'];
    const cookMM = cookRes['rain_mean'];

    if (cairnsMM === null || cookMM === null || !isFinite(cairnsMM) || !isFinite(cookMM)) {
      console.log('Calculation produced null/invalid value.');
      console.log('C3');
      return;
    }

    console.log(`Date window: ${start} to 2025-02-04`);
    console.log(`Cairns rain (mm): ${cairnsMM.toFixed(1)} | pixels: ${cairnsPx}`);
    console.log(`Cooktown rain (mm): ${cookMM.toFixed(1)} | pixels: ${cookPx}`);

    // 5. Final Answer
    if (cairnsMM > cookMM) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
